inline EnemyBehaviour const* FindEnemyBehaviour(std::uint32_t entry) {
    for (auto const& b : EnemyBehaviours) if (b.Entry == entry) return &b;
    return nullptr;
}
inline EnemyVariant const* FindEnemyVariant(std::uint32_t entry) {
    for (auto const& variant : EnemyVariants) if (variant.Entry == entry) return &variant;
    return nullptr;
}
inline std::int32_t EnemyFlatArmour(std::uint32_t entry) {
    auto const* variant = FindEnemyVariant(entry);
    return variant && variant->SourceCombat ? variant->FlatArmour : 0;
}
inline std::uint32_t EnemyDefenceLevel(std::uint32_t entry, std::uint32_t defence, std::uint32_t magic) {
    auto const* variant = FindEnemyVariant(entry);
    return variant && variant->SourceCombat && variant->MeleeLane == 3
        ? (7*magic)/10+(3*defence)/10 : defence;
}
inline std::uint32_t EnemyMaximumHit(std::uint32_t entry, std::uint32_t fallback) {
    auto const* variant = FindEnemyVariant(entry);
    return variant && variant->SourceCombat ? variant->MaximumHit : fallback;
}
inline std::int32_t EnemyMeleeDefence(std::uint32_t entry, std::uint8_t lane, std::int32_t fallback) {
    auto const* variant = FindEnemyVariant(entry);
    if (!variant || !variant->SourceCombat) return fallback;
    switch (lane) {
        case 0: return variant->DefenceStab;
        case 1: return variant->DefenceSlash;
        case 2: return variant->DefenceCrush;
        default: return fallback;
    }
}
template<class Draw32> inline std::uint64_t DrawEnemyLootRoll(std::uint64_t total, Draw32 draw) {
    if (!total) return 0;
    std::uint64_t const threshold = (std::uint64_t(0)-total)%total;
    for (;;) {
        std::uint64_t const high = draw();
        std::uint64_t const value = (high<<32)|std::uint64_t(draw());
        if (value >= threshold) return value%total;
    }
}
inline EnemyLootPool const* FindEnemyLootPool(std::uint32_t entry) {
    for (auto const& pool : EnemyLootPools) if (pool.Entry == entry) return &pool;
    return nullptr;
}
inline std::uint32_t SelectEnemyLoot(std::uint32_t entry, std::uint64_t roll) {
    auto const* pool = FindEnemyLootPool(entry);
    if (!pool || roll >= pool->Total) return 0;
    for (std::uint32_t i = pool->First; i < pool->First + pool->Count; ++i) {
        auto const& outcome = EnemyLootOutcomes[i];
        if (roll < outcome.Weight) return outcome.Loot;
        roll -= outcome.Weight;
    }
    return 0;
}
